(function () {
  const sourceTitle = "AP Cybersecurity Course and Exam Description — College Board";
  const sourceUrl = "https://apcentral.collegeboard.org/media/pdf/ap-cybersecurity-course-and-exam-description.pdf";
  const makeDeck = (unit, name, terms, prompts) => ({
    id: `apcyber-unit-${unit}`, name: `AP Cybersecurity · Unit ${unit}`, shortName: name, builtIn: true,
    sourceTitle, sourceUrl,
    cards: terms.map(([front, back], index) => ({ id: `apcyber-u${unit}-c${index + 1}`, front, back })),
    questions: [],
    feynmanPrompts: prompts.map((prompt, index) => ({ id: `apcyber-u${unit}-f${index + 1}`, prompt })),
  });

  window.AP_CYBERSECURITY_DECKS = [
    makeDeck(1, "Introduction to Security", [
      ["Cybersecurity", "The practice of protecting systems, networks, devices, and data from unauthorized access, disruption, alteration, or destruction."],
      ["Confidentiality", "The security objective that information is accessible only to authorized people, processes, or systems."],
      ["Integrity", "The security objective that information and systems remain accurate, complete, and protected from unauthorized modification."],
      ["Availability", "The security objective that authorized users can access information and services when needed."],
      ["Threat", "A circumstance or event with the potential to harm an asset by exploiting a vulnerability."],
      ["Vulnerability", "A weakness in technology, procedure, configuration, or human behavior that a threat can exploit."],
      ["Risk", "The potential for loss or harm when a threat exploits a vulnerability, considering likelihood and impact."],
      ["Attack surface", "The total set of points through which an attacker could attempt to enter, extract data from, or affect a system."],
      ["Social engineering", "Manipulation that exploits trust, urgency, fear, curiosity, or authority to persuade a person to reveal information or perform an unsafe action."],
      ["Phishing", "A deceptive message that impersonates a trusted source to steal information, deliver malware, or induce an unsafe action."],
      ["Spear phishing", "A phishing attack tailored to a particular person or organization using specific personal or professional details."],
      ["Smishing", "Phishing conducted through SMS or another text-messaging service."],
      ["Vishing", "Phishing conducted through voice calls or voice messages."],
      ["Pretexting", "A social-engineering technique that uses an invented scenario or identity to obtain information or action."],
      ["Multi-factor authentication", "Authentication using at least two different factor types, such as something known, possessed, or inherent."],
      ["Password manager", "Software that generates, stores, and fills strong unique passwords in an encrypted vault."],
      ["Credential stuffing", "Automated attempts to reuse username-password pairs stolen from one service on other services."],
      ["Brute-force attack", "Systematic attempts to discover a secret by trying many possible values."],
      ["Dictionary attack", "A password attack that tries words, common passwords, and predictable variations rather than every possible character sequence."],
      ["HTTPS", "HTTP protected with TLS, providing encrypted communication and server authentication when correctly configured."],
      ["Public Wi-Fi risk", "The possibility that untrusted network users or equipment may observe, redirect, or manipulate traffic, especially when connections lack encryption."],
      ["Virtual private network", "A technology that creates an encrypted tunnel between a device and a VPN endpoint; it protects traffic on the local network but does not make all activity anonymous or safe."],
      ["Deepfake", "Synthetic or manipulated media generated to convincingly imitate a person's face, voice, or actions."],
      ["Adversarial AI", "Use of artificial intelligence to improve attacks or deliberate manipulation of AI systems and their inputs."],
    ], ["Social engineering and AI-enabled attacks", "Passwords, authentication, and individual defenses"]),

    makeDeck(2, "Securing Spaces", [
      ["Physical security", "Controls that protect people, facilities, hardware, and other tangible assets from unauthorized access, theft, damage, or environmental hazards."],
      ["Tailgating", "Entering a restricted area by closely following an authorized person without presenting valid credentials."],
      ["Badge access", "A physical access-control system that uses an issued credential to identify a person and permit or deny entry."],
      ["Biometric authentication", "Identity verification using measurable biological or behavioral traits such as fingerprints, facial features, or voice patterns."],
      ["Least privilege", "Granting each user, process, or device only the permissions needed to perform its authorized tasks."],
      ["Role-based access control", "An access model in which permissions are assigned to job roles and users receive permissions through their roles."],
      ["Discretionary access control", "An access model in which an object's owner decides who may access it and what operations are allowed."],
      ["Mandatory access control", "A centrally enforced access model using security labels and clearances that users and ordinary owners cannot override."],
      ["File permission", "A rule defining which identities may read, write, or execute a file or directory."],
      ["Administrative account", "An account with elevated permissions to configure systems, install software, and manage other accounts."],
      ["Account lockout", "A control that temporarily or permanently blocks login after a defined number of failed attempts."],
      ["Patch", "A software update that corrects defects, including vulnerabilities that could be exploited."],
      ["System hardening", "Reducing attack surface by securely configuring a system, removing unnecessary services, applying updates, and restricting privileges."],
      ["Secure baseline", "An approved minimum configuration used as a consistent starting point for securely deploying systems."],
      ["Full-disk encryption", "Encryption that protects data stored on a drive when the device is powered off or the drive is removed."],
      ["Data at rest", "Data stored on media rather than actively moving across a network or being processed."],
      ["Data in transit", "Data moving between systems or locations through a network."],
      ["Backup", "A separate copy of data used to restore information after deletion, corruption, device failure, or attack."],
      ["3-2-1 backup rule", "Keeping three copies of data on two different media types with one copy stored off-site or otherwise isolated."],
      ["Secure deletion", "Removal that makes stored data impractical to recover, using appropriate wiping, cryptographic erasure, or media destruction."],
      ["Removable-media risk", "The possibility that portable storage introduces malware, loses sensitive data, or bypasses normal network controls."],
      ["Mobile device management", "Central administration that applies configuration, update, access, and remote-wipe policies to mobile endpoints."],
      ["Internet of Things device", "A network-connected physical device with sensors or controls that may create risk through weak credentials, limited updates, or insecure communications."],
      ["Security policy", "A documented rule describing required or prohibited behavior for protecting an organization's assets."],
    ], ["Layered physical and logical access controls", "Device hardening, data protection, and recovery"]),

    makeDeck(3, "Securing Networks", [
      ["Network segmentation", "Dividing a network into controlled sections to reduce attack surface and limit unauthorized movement between resources."],
      ["Firewall", "A security control that permits or blocks network traffic according to defined rules."],
      ["Firewall rule", "A condition and action that evaluates traffic attributes such as source, destination, port, protocol, and connection state."],
      ["Default deny", "A policy that blocks access unless a rule explicitly permits it."],
      ["Port", "A numbered logical endpoint used to direct network traffic to a particular application or service."],
      ["Protocol", "An agreed set of rules governing how systems format, transmit, receive, and interpret data."],
      ["IP address", "A numerical identifier used to locate and route traffic to a device or interface on an IP network."],
      ["MAC address", "A data-link-layer identifier assigned to a network interface and used for local network communication."],
      ["Domain Name System", "The distributed naming system that translates domain names into IP addresses and other records."],
      ["DNS spoofing", "Supplying false DNS information so traffic is redirected to an unintended destination."],
      ["Packet", "A formatted unit of data transmitted across a packet-switched network."],
      ["Packet capture", "Recorded network traffic used to troubleshoot communication or investigate suspicious activity."],
      ["Network address translation", "A technique that maps private internal addresses to one or more public addresses as traffic crosses a gateway."],
      ["Wireless access point", "A device that connects wireless clients to a wired network."],
      ["WPA3", "A modern Wi-Fi security standard providing stronger authentication and encryption than earlier WPA versions."],
      ["Rogue access point", "An unauthorized wireless access point connected to or imitating an organization's network."],
      ["Man-in-the-middle attack", "An attack in which an adversary secretly intercepts and may alter communication between parties."],
      ["Denial-of-service attack", "An attack intended to exhaust resources or otherwise make a service unavailable to legitimate users."],
      ["Distributed denial-of-service attack", "A denial-of-service attack launched from many compromised systems at once."],
      ["Intrusion detection system", "A control that monitors activity and alerts when it detects suspicious patterns or policy violations."],
      ["Intrusion prevention system", "A control that monitors traffic and can automatically block detected malicious activity."],
      ["Virtual local area network", "A logical broadcast domain that separates devices on shared switching infrastructure."],
      ["Demilitarized zone", "A network segment that isolates public-facing services from an organization's internal network."],
      ["Zero trust", "A security approach that grants no implicit trust based on network location and continually evaluates access to resources."],
    ], ["How firewall rules and segmentation control network traffic", "Attacks against network availability and traffic integrity"]),

    makeDeck(5, "Securing Applications and Data", [
      ["Encryption", "Transformation of plaintext into ciphertext using a cryptographic algorithm and key so unauthorized readers cannot understand it."],
      ["Plaintext", "Readable original data before encryption or after successful decryption."],
      ["Ciphertext", "The unreadable output produced when plaintext is encrypted."],
      ["Symmetric encryption", "Encryption in which the same secret key is used to encrypt and decrypt data."],
      ["Asymmetric encryption", "Encryption using a mathematically related public key and private key for different operations."],
      ["Public key", "The shareable key in an asymmetric key pair, commonly used to encrypt for the owner or verify the owner's signature."],
      ["Private key", "The secret key in an asymmetric key pair, commonly used to decrypt or create digital signatures."],
      ["Hash function", "A one-way function that maps data to a fixed-length digest and is designed to make input recovery and collisions difficult."],
      ["Salt", "A unique random value combined with a password before hashing to defeat precomputed lookup attacks and make identical passwords produce different hashes."],
      ["Digital signature", "A cryptographic value created with a private key to support origin authentication, integrity, and nonrepudiation."],
      ["Digital certificate", "A signed electronic document that binds a public key to an identified subject."],
      ["Certificate authority", "A trusted organization that validates identities and signs digital certificates."],
      ["Public key infrastructure", "The policies, roles, hardware, software, and procedures used to issue, manage, validate, and revoke digital certificates."],
      ["Input validation", "Checking untrusted input for acceptable type, length, format, and range before processing it."],
      ["SQL injection", "An attack that inserts crafted database commands through untrusted input handled by an unsafe query."],
      ["Cross-site scripting", "Injection of malicious script into content that another user's browser treats as trusted by a website."],
      ["Buffer overflow", "Writing beyond an allocated memory boundary, potentially causing crashes or unauthorized code execution."],
      ["Secure coding", "Designing, implementing, reviewing, and testing software to prevent vulnerabilities and handle failures safely."],
      ["Data classification", "Categorizing data by sensitivity and impact so appropriate handling and protection requirements can be applied."],
      ["Data minimization", "Collecting, using, and retaining only the data necessary for a defined purpose."],
      ["Personally identifiable information", "Information that can identify a specific person alone or when combined with other data."],
      ["Tokenization", "Replacing sensitive data with a non-sensitive token while storing the original value in a separately protected system."],
      ["Data loss prevention", "Policies and technologies that identify sensitive data and prevent unauthorized disclosure or transfer."],
      ["Application programming interface key", "A credential used by software to identify and authorize access to an API; it must be protected like other secrets."],
    ], ["Encryption, hashing, signatures, and digital trust", "Secure software and defenses against injection attacks"]),

    makeDeck(4, "Securing Devices", [
      ["Security log", "A time-stamped record of events generated by systems, applications, or security controls for monitoring and investigation."],
      ["Log correlation", "Connecting events from multiple sources to identify a pattern that individual records may not reveal."],
      ["Security information and event management", "A platform that centralizes, normalizes, correlates, and alerts on security log data."],
      ["Indicator of compromise", "Observable evidence suggesting that a system or network may have been breached."],
      ["Baseline behavior", "A documented or measured pattern of normal activity used to identify meaningful deviations."],
      ["Anomaly detection", "Identification of activity that differs significantly from an established pattern of normal behavior."],
      ["False positive", "A benign event incorrectly classified as malicious."],
      ["False negative", "Malicious activity incorrectly classified as benign or missed entirely."],
      ["Signature-based detection", "Detection that compares activity with known patterns associated with particular threats."],
      ["Behavior-based detection", "Detection that identifies suspicious actions or deviations rather than relying only on known attack signatures."],
      ["Malware", "Software or code intentionally designed to disrupt operations, damage systems, spy, or gain unauthorized access."],
      ["Virus", "Malware that attaches to a host file or program and spreads when that host executes."],
      ["Worm", "Self-replicating malware that spreads across systems or networks without needing a host file."],
      ["Trojan horse", "Malware disguised as legitimate or desirable software to persuade a user to install or run it."],
      ["Ransomware", "Malware that denies access to data or systems, often through encryption, and demands payment."],
      ["Rootkit", "Tools designed to maintain privileged, concealed access to a compromised system."],
      ["Incident response", "The organized process of preparing for, detecting, containing, eradicating, recovering from, and learning from security incidents."],
      ["Containment", "Incident-response actions that limit an attack's spread and reduce additional harm while preserving necessary evidence."],
      ["Eradication", "Removal of malicious artifacts, compromised accounts, persistence mechanisms, and root causes from affected systems."],
      ["Recovery", "Safe restoration of systems and services, followed by validation and heightened monitoring."],
      ["Chain of custody", "Documentation showing who collected, handled, transferred, stored, and analyzed evidence from collection through disposition."],
      ["Digital forensics", "The disciplined identification, preservation, examination, and interpretation of digital evidence."],
      ["Defense in depth", "Use of multiple independent and overlapping controls so the failure of one does not leave an asset unprotected."],
      ["Playbook", "A documented sequence of roles, decisions, and actions for responding consistently to a defined incident type."],
    ], ["Reading logs and recognizing evidence of attack", "Detection methods, incident response, and evidence preservation"]),
  ].sort((a, b) => a.id.localeCompare(b.id));
})();
